const KEY='emotion-learning-v1';
const blank=()=>({weeks:[],papers:[],notes:{},quizBest:0,inProgress:[],checks:{},lastVisited:null,lastExportAt:null,updatedAt:null});
function validate(v){if(!v||typeof v!=='object')throw Error('格式不正确');return {...blank(),inProgress:[...new Set((Array.isArray(v.inProgress)?v.inProgress:[]).filter(p=>/^P(0[1-9]|[12][0-9]|3[0-6])$/.test(p)&&!(Array.isArray(v.papers)?v.papers:[]).includes(p)))],checks:Object.fromEntries(Object.entries(v.checks&&typeof v.checks==='object'?v.checks:{}).filter(([k,t])=>typeof t==='boolean'&&k.length<1000)),lastVisited:v.lastVisited&&['week','paper'].includes(v.lastVisited.type)&&/^(?:[1-9]|1[0-9]|2[0-8]|P(?:0[1-9]|[12][0-9]|3[0-6]))$/.test(String(v.lastVisited.id))?v.lastVisited:null,lastExportAt:typeof v.lastExportAt==='string'?v.lastExportAt:null,updatedAt:typeof v.updatedAt==='string'?v.updatedAt:null,weeks:[...new Set((Array.isArray(v.weeks)?v.weeks:[]).filter(n=>Number.isInteger(n)&&n>=1&&n<=28))],papers:[...new Set((Array.isArray(v.papers)?v.papers:[]).filter(p=>/^P(0[1-9]|[12][0-9]|3[0-6])$/.test(p)))],notes:Object.fromEntries(Object.entries(v.notes&&typeof v.notes==='object'?v.notes:{}).filter(([k,t])=>/^(journal|week-([1-9]|1[0-9]|2[0-8])|P(0[1-9]|[12][0-9]|3[0-6]))$/.test(k)&&typeof t==='string').map(([k,t])=>[k,t.slice(0,20000)])),quizBest:Math.max(0,Math.min(12,Number(v.quizBest)||0))};}
let state=blank(),storageOK=true;
try{state=validate(JSON.parse(localStorage.getItem(KEY)||'null')||blank());}catch(e){storageOK=false;}
let saveTimer;
function flushSave(){clearTimeout(saveTimer);try{state.updatedAt=new Date().toISOString();localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;document.querySelectorAll('.save-hint').forEach(el=>el.textContent='已保存 · 刚刚 · 可在笔记页导出');}catch(e){storageOK=false;document.querySelectorAll('.save-hint').forEach(el=>el.textContent='未能保存，请复制笔记或导出备份');toast('浏览器无法保存，请在笔记页导出备份。');}}
function save(deferred=false){clearTimeout(saveTimer);if(deferred){document.querySelectorAll('.save-hint').forEach(el=>el.textContent='正在保存…');saveTimer=setTimeout(flushSave,300);}else flushSave();}
addEventListener('pagehide',()=>{if(saveTimer)flushSave();});
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),2600);}
