let page='home',routeFilter='all',paperFilter='all',paperSearch='',paperStatus='all',paperDepth='all',bookSection='s1',quizIndex=0,answers=[];
const groupTag=g=>`<span class="tag ${colors[g]}">${names[g]}</span>`;
const intro=(en,title,desc)=>`<div class="page-intro"><h1>${title}</h1><p>${desc}</p></div>`;
const phases=[
{g:'common',from:1,to:8,range:'01—08',title:'打好共同基础',short:'读懂数据、训练与 ALMT',goal:'读懂一条样本，跑通训练闭环，沿代码理解 ALMT 并完成模态消融。'},
{g:'fine',from:9,to:16,range:'09—16',title:'进入细粒度理解',short:'从多标签到可信描述',goal:'把情感倾向拆成多标签与强度，再走向有证据、可核查的描述与开放词汇。'},
{g:'cross',from:17,to:24,range:'17—24',title:'理解跨场景学习',short:'观察遗忘，再尝试解决',goal:'先亲眼观察灾难性遗忘，再比较蒸馏、参数约束与场景状态建模。'},
{g:'research',from:25,to:28,range:'25—28',title:'形成研究闭环',short:'用公平实验支持结论',goal:'锁定一个可检验的问题，完成正式实验、误差分析与可复查报告。'}];
const phaseDone=ph=>state.weeks.filter(n=>n>=ph.from&&n<=ph.to).length;
const phaseSize=ph=>ph.to-ph.from+1;
// Route logic: common base first, then ONE branch (A fine-grained or B cross-scene), then the shared research loop.
function routeStatus(){const done=phases.map(ph=>phaseDone(ph)===phaseSize(ph)),fd=phaseDone(phases[1]),xd=phaseDone(phases[2]),branch=xd>fd?2:1;const current=!done[0]?0:!done[branch]?branch:done[3]?4:3;const skip=done[0]&&(fd||xd)&&phaseDone(phases[3-branch])===0?3-branch:-1;return {current,branch,skip,choosing:done[0]&&!fd&&!xd};}
function focusWeek(){const ph=phases[routeStatus().current];return (ph&&weeks.find(w=>w.n>=ph.from&&w.n<=ph.to&&!state.weeks.includes(w.n)))||weeks.find(w=>!state.weeks.includes(w.n));}
function milestones(){const rs=routeStatus();return `<ol class="milestones" aria-label="学习里程碑">${phases.map((ph,i)=>{const d=phaseDone(ph),t=phaseSize(ph),full=d===t,skip=i===rs.skip,cur=i===rs.current;const here=cur?(rs.choosing?'下一步：A / B 二选一':'你在这里'):skip?'已选另一分支，可跳过':'';return `<li class="milestone dir-${ph.g} ${full?'is-done':cur?'is-current':''} ${skip?'is-skip':''}" style="--i:${i};--seg:${(skip?1:d/t).toFixed(3)}"><a href="#roadmap/${ph.g}"${cur?' aria-current="step"':''}><span class="milestone-dot" aria-hidden="true">${full?'✓':i+1}</span><small>第 ${ph.range} 周</small><h3>${ph.title}</h3><p>${ph.short}</p><span class="milestone-count">${d} / ${t} 已验收</span>${here?`<em class="here">${here}</em>`:''}</a></li>`;}).join('')}</ol>`;}
function trackCard(g){const A=g==='fine',ph=phases[A?1:2],d=phaseDone(ph),base=phaseDone(phases[0]),baseDone=base===8,steps=A?['多标签','强度','证据','描述','开放词汇']:['域偏移','遗忘','LwF','EWC','EmWorld'],lit=Math.round(d/8*steps.length);return `<article class="card track-card dir-${g}"><div class="track-heading"><b>${A?'A':'B'}</b>${groupTag(g)}</div><h3>${A?'从情绪标签，到有依据的理解':'适应新场景，也记得旧知识'}</h3><p>${A?'不只判断正面或负面。学习识别多种情绪、估计强度，并用可观察证据解释判断。':'面对环境变化，观察模型怎样遗忘，再学习蒸馏、参数约束与场景状态建模。'}</p><ol class="path-steps" aria-label="${A?'细粒度':'跨场景'}方向学习路径">${steps.map((s,i)=>`<li class="${i<lit?'lit':''}" style="--i:${i}">${s}</li>`).join('')}</ol><div class="track-meter"><span class="track-position">${baseDone?`分支验收：${d} / 8 个阶段`:`当前位置：共同基础 ${base} / 8 · ${A?'先读懂输入、输出与监督':'先跑通训练与评价'}`}</span><div class="progress-track"><div style="width:${(baseDone?d:base)/8*100}%"></div></div></div><a href="#roadmap/${g}">${A?'探索细粒度方向':'探索跨场景方向'} →</a></article>`;}
