function resumeTarget(){const last=state.lastVisited;if(last?.type==='paper'){const p=COURSE.papers.find(x=>x.id===last.id);if(p&&!state.papers.includes(p.id))return {title:p.id+' · '+p.title,desc:'继续阅读概念、公式与源码，写下仍不理解的一步。',control:`data-paper="${p.id}"`,label:'继续读这篇',meta:'论文精读'};}const n=last?.type==='week'?weeks.find(w=>w.n===+last.id&&!state.weeks.includes(w.n)):null;const w=n||focusWeek();return w?{title:`第 ${w.n} 周 · ${w.title}`,desc:w.action,control:`data-week="${w.n}"`,label:state.lastVisited?'继续学习':'打开第一份任务单',meta:'先做最小任务，再核对验收'}:{title:'所有阶段已勾选完成',desc:'回到笔记，选择一个仍未解决的问题继续验证。',control:'data-resume-notes="true"',label:'回顾学习笔记',meta:'下一步：复查研究证据'};}
function home(){const next=resumeTarget(),pc=Math.round(state.weeks.length/28*100),checks=Object.values(state.checks).filter(Boolean).length,rs=routeStatus(),base=phaseDone(phases[0]);return `<section class="hero"><div class="hero-copy"><h1><span class="line"><span>把好奇心，</span></span><span class="line"><span>变成<em>研究的第一步</em>。</span></span></h1><p>从读懂一条样本，到解释一个模型。沿着两条研究路线，逐步理解情绪，让每一次学习都落到可验证的小实验。</p><div class="actions"><a class="btn primary" href="#roadmap">查看学习路线 →</a><a class="btn" href="#lab">先动手试一试</a></div><ul class="hero-stats" aria-label="学习内容概览">${[[28,'周分步路线'],[COURSE.papers.length,'篇完整精读'],[2,'个概念实验'],[8,'道理解自测']].map(([n,t],i)=>`<li style="--i:${i}"><b data-count="${n}">${n}</b><small>${t}</small></li>`).join('')}</ul></div><div class="hero-art">${art}</div></section>
<section class="resume-strip" aria-label="学习进度"><div class="resume-main"><p class="resume-context">${esc(next.meta)}</p><h2>${esc(next.title)}</h2><p>${esc(next.desc)}</p><div class="actions"><button class="btn primary" ${next.control}>${next.label} →</button><a href="#handbook/s11">首周七天清单</a></div></div><div class="progress-summary"><div class="ring-wrap"><svg viewBox="0 0 100 100" class="ring" aria-hidden="true"><circle class="ring-base" cx="50" cy="50" r="42"/><circle class="ring-value" cx="50" cy="50" r="42" pathLength="100" style="stroke-dashoffset:${100-pc}"/></svg><strong><span data-count="${pc}" data-count-key="ring-pc">${pc}</span><small>%</small></strong></div><p aria-live="polite">已完成 ${state.weeks.length} / 28 个阶段</p><small>已读 ${state.papers.length} / ${COURSE.papers.length} 篇 · 自测 ${state.quizBest} / ${questions.length}<br>手册清单已勾选 ${checks} 项</small></div></section>
<div class="section-head"><h2>一条路线，四个里程碑</h2><a href="#handbook/s2">如何安排学习 →</a></div><p class="section-sub">先打共同基础，再在 A、B 中选一条分支，最后汇合到研究闭环。连线按每个阶段的真实验收进度填充。</p>${milestones()}
<div class="section-head"><h2>选择你的探索方向</h2><a href="#handbook/s1">先了解研究问题 →</a></div><p class="section-sub">${base<8?'两条分支共用前 8 周基础；完成后只需选择其一。':rs.choosing?'共同基础已完成：现在选择一条分支，另一条可以跳过。':`已在 ${rs.branch===1?'A 细粒度':'B 跨场景'} 分支推进，另一条可作为选读。`}</p><div class="two-col">${trackCard('fine')}${trackCard('cross')}</div>`;}
const forks={1:'共同基础完成后 · <b class="a">A 细粒度</b> 与 <b class="b">B 跨场景</b> 二选一',2:'或者选择 <b class="b">B 跨场景</b>',3:'两条分支在此汇合 · 进入研究闭环'};
function weekCard(w,next){const done=state.weeks.includes(w.n),isNext=!!next&&next.n===w.n;return `<article class="week dir-${w.group} ${done?'done':''} ${isNext?'is-next':''}">${isNext?'<span class="next-badge">下一步</span>':''}<span class="week-num">${String(w.n).padStart(2,'0')}</span><div class="week-body">${groupTag(w.group)}<h3 style="margin-top:9px">${w.title}</h3><p>${w.sub}</p>${w.papers.length?`<div class="week-papers"><span>关联论文</span>${w.papers.map(id=>`<button type="button" class="paper-chip" data-paper="${id}" aria-label="打开 ${id} 逐节精读">${id}</button>`).join('')}</div>`:''}<div class="actions"><button class="btn small" data-week="${w.n}">打开分步任务单 →</button><label class="check"><input type="checkbox" data-week-check="${w.n}" ${done?'checked':''}>已完成</label></div></div></article>`;}
function roadmap(){const next=focusWeek(),all=routeFilter==='all';return intro('YOUR LEARNING PATH','一步一步，走到自己的研究问题。','先完成共同基础，再只选一条分支。每周都有操作顺序、文件入口、必交产物和停止条件；周数是任务编号，可以按掌握情况放慢。')+`<div class="progress-banner"><div><strong>已完成 ${state.weeks.length} / 28 个学习阶段</strong><p>已有 ALMT 实验不必重跑：先做 W01 数据核查、W07 形状追踪，再进入 W08 消融。学习勾选不代表实验已经执行。</p></div><div><small>${Math.round(state.weeks.length/28*100)}% 完成</small><div class="progress-track"><div style="width:${state.weeks.length/28*100}%"></div></div></div></div><div class="toolbar chips">${['all','common','fine','cross','research'].map(g=>`<button class="chip ${g===routeFilter?'active':''}" data-route-filter="${g}" aria-pressed="${g===routeFilter}">${g==='all'?'完整路线':names[g]}</button>`).join('')}</div>${phases.map((ph,i)=>{if(!all&&ph.g!==routeFilter)return '';const d=phaseDone(ph),t=phaseSize(ph);return `${all&&forks[i]?`<div class="phase-fork"><span>${forks[i]}</span></div>`:''}<section class="phase dir-${ph.g}" aria-labelledby="phase-${ph.g}"><header class="phase-head"><span class="phase-index" aria-hidden="true">${i+1}</span><div><h2 id="phase-${ph.g}">${ph.title}<small>第 ${ph.range} 周</small></h2><p>${ph.goal}</p></div><div class="phase-progress"><strong>${d}</strong> / ${t} 已验收<div class="progress-track"><div style="width:${d/t*100}%"></div></div></div></header><div class="week-grid">${weeks.filter(w=>w.n>=ph.from&&w.n<=ph.to).map(w=>weekCard(w,next)).join('')}</div></section>`;}).join('')}`;}
const deepPapers={"P01":{"slug":"attention","name":"Transformer"},"P02":{"slug":"bert","name":"BERT"},"P03":{"slug":"clip","name":"CLIP"},"P04":{"slug":"wav2vec2","name":"wav2vec 2.0"},"P05":{"slug":"mult","name":"MulT"},"P06":{"slug":"almt","name":"ALMT"},"P07":{"slug":"ch-sims","name":"CH-SIMS"},"P08":{"slug":"mosei","name":"CMU-MOSEI"},"P09":{"slug":"norm-tr","name":"NORM-TR"},"P10":{"slug":"emer","name":"EMER"},"P11":{"slug":"ovmer","name":"OV-MER"},"P12":{"slug":"affectgpt","name":"AffectGPT"},"P13":{"slug":"ecpa","name":"ECPA"},"P14":{"slug":"cera","name":"CERA"},"P15":{"slug":"lora","name":"LoRA"},"P16":{"slug":"est","name":"EST"},"P17":{"slug":"dann","name":"DANN"},"P18":{"slug":"lwf","name":"LwF"},"P19":{"slug":"ewc","name":"EWC"},"P20":{"slug":"gpm","name":"GPM"},"P21":{"slug":"emworld","name":"EmWorld"},"P22":{"slug":"ferv39k","name":"FERV39k"},"P23":{"slug":"pcl","name":"PCL"},"P24":{"slug":"pcfrl","name":"PCFRL"},"P25":{"slug":"resnet","name":"ResNet"},"P26":{"slug":"simclr","name":"SimCLR"}};
function paperCards(){let list=COURSE.papers.filter(p=>(paperDepth==='all'||(paperDepth==='core'?p.core:!p.core))&&(paperFilter==='all'||p.group===paperFilter)&&(paperStatus==='all'||(paperStatus==='core'?p.core:paperStatus==='read'?state.papers.includes(p.id):paperStatus==='reading'?state.inProgress.includes(p.id):!state.papers.includes(p.id)&&!state.inProgress.includes(p.id)))&&`${p.id} ${p.title} ${p.summary} ${p.meta} ${p.searchText||''}`.toLowerCase().includes(paperSearch.toLowerCase()));return `<p class="mode-notice" aria-live="polite">找到 ${list.length} 篇 · 26 篇完整学术精读 · <a href="deep/index.html">查看精读目录 →</a></p><div class="paper-grid">${list.length?list.map(p=>`<article class="card paper"><div class="paper-top"><span class="paper-meta"><span class="paper-id">${p.id}</span>${state.papers.includes(p.id)?'<span class="status-pill read">已读</span>':state.inProgress.includes(p.id)?'<span class="status-pill reading">在读</span>':''}</span><div>${groupTag(p.group)}<span class="tag amber">${p.core?'重点阅读':'方法 / 选读'}</span>${+p.id.slice(1)>26?'<span class="tag new">2026-10 新增</span>':''}</div></div><h3>${esc(p.title)}</h3><p>${esc(p.summary)}</p><div class="paper-bottom">${deepPapers[p.id]?`<a class="btn primary small" href="deep/${deepPapers[p.id].slug}.html">完整学术精读 →</a>`:''}<button class="btn small" data-paper="${p.id}">开始逐节精读 →</button><label class="reading-state">阅读状态<select data-reading-state="${p.id}" aria-label="${p.id} 阅读状态">${[["unread","未读"],["reading","在读"],["read","已读"]].map(([v,t])=>`<option value="${v}" ${(state.papers.includes(p.id)?"read":state.inProgress.includes(p.id)?"reading":"unread")===v?"selected":""}>${t}</option>`).join('')}</select></label></div></article>`).join(''):'<div class="empty">没有匹配的论文。试试清空关键词或选择「全部」。</div>'}</div>`;}
function papers(){return intro('THE READING ROOM','不急着读完，先读懂一篇。','26 篇完整学术精读，逐步解释概念、公式、源码与实验，附具体练习和验收要求。可搜索基础讲义中的术语，或进入完整精读目录。')+`<div class="toolbar"><label class="skip-label" for="paper-search">搜索</label><input id="paper-search" class="search" placeholder="搜索 ALMT、遗忘、情绪、作者或论文标题…" value="${esc(paperSearch)}"><select id="paper-status" aria-label="筛选阅读状态">${[['all','全部阅读状态'],['unread','尚未开始'],['reading','正在阅读'],['read','已经读过']].map(([v,t])=>`<option value="${v}" ${v===paperStatus?'selected':''}>${t}</option>`).join('')}</select><select id="paper-depth" aria-label="筛选阅读深度">${[['all','全部阅读深度'],['core','重点精读'],['method','方法 / 选读']].map(([v,t])=>`<option value="${v}" ${v===paperDepth?'selected':''}>${t}</option>`).join('')}</select></div><div class="chips">${['all','common','fine','cross'].map(g=>`<button class="chip ${g===paperFilter?'active':''}" data-paper-filter="${g}" aria-pressed="${g===paperFilter}">${g==='all'?'全部论文':names[g]}</button>`).join('')}</div><div id="paper-results">${paperCards()}</div>`;}
function handbook(){let section=COURSE.sections.find(s=>s.id===bookSection)||COURSE.sections[0];return intro('THE COMPLETE HANDBOOK','完整内容，随时回到原理。','保留完整路线、论文方法、数据协议、研究项目与记录模板。长表格可以左右滚动。')+`<div class="reader-layout"><nav class="contents" aria-label="手册目录">${COURSE.sections.map(s=>`<button data-section="${s.id}" class="${section.id===s.id?'active':''}" ${section.id===s.id?'aria-current="location"':''}>${esc(s.title)}</button>`).join('')}</nav><article class="card prose handbook-content" data-book-section="${section.id}"><h2>${esc(section.title)}</h2>${section.html}</article></div>`;}
function noteArea(id,label='我的思考与问题'){return `<label class="note-label" for="note-${id}">${label}</label><textarea class="note-editor" id="note-${id}" data-note="${id}" placeholder="用自己的话记录：我理解了什么？哪一步仍然不懂？下一次要验证什么？">${esc(state.notes[id]||'')}</textarea><span class="save-hint" role="status" aria-live="polite">自动保存在当前浏览器 · 可在「我的学习笔记」中导出</span>`;}
function openDialog(label,body){$('#dialog-label').textContent=label;$('#dialog-content').innerHTML=body;if(!$('#reader').open)$('#reader').showModal();$('#reader').scrollTop=0;enhanceProse($('#dialog-content'));}
function lessonBlocks(parts){return `<div class="lesson-stack">${parts.map((part,i)=>`<details class="lesson-part" ${i===0?'open':''}><summary><span class="lesson-number">${String(i+1).padStart(2,'0')}</span>${esc(part.title)}</summary><div class="prose lesson-text">${part.html}</div></details>`).join('')}</div>`;}
function readerTools(download){return `<div class="actions reader-tools"><button class="btn small" data-lessons="expand">展开全部章节</button><button class="btn small" data-lessons="collapse">收起全部章节</button><a class="btn small" href="${download}" download>下载详细讲义 ↓</a></div>`;}
function openWeek(n){let w=weeks[n-1];if(!w)return;state.lastVisited={type:'week',id:n};save();let parts=COURSE.weekLessons['W'+String(n).padStart(2,'0')];openDialog(`WEEK ${String(n).padStart(2,'0')} · ${names[w.group]}`,`<div class="prose"><h2>${w.title}</h2><p class="muted">${w.sub}</p></div><div class="info">先做本周最小任务 → 保存产物 → 对照验收。前置条件缺失就先处理缺口。</div>${readerTools('week-playbook.md')}${lessonBlocks(parts)}<div class="prose"><h4>本周论文入口</h4><div class="actions">${w.papers.length?w.papers.map(id=>`<button class="btn small" data-paper="${id}">${id} · ${esc(COURSE.papers.find(p=>p.id===id).title.split(':')[0])}</button>`).join(''):'<p>围绕已选分支的关键论文与实验记录。</p>'}</div><div class="actions"><a class="btn small" href="learning_starter.py" download>下载入门练习脚本 ↓</a><label class="check"><input type="checkbox" data-week-check="${n}" ${state.weeks.includes(n)?'checked':''}>产物已完成且通过验收</label></div></div>${noteArea('week-'+n)}`);}
function openPaper(id){let p=COURSE.papers.find(p=>p.id===id);if(!p)return;markReading(id);if($('#reader').open)$('#reader').close();openDialog(`${p.id} · ${names[p.group]}`,`<div class="prose"><h2>${esc(p.title)}</h2></div><div class="info">精读顺序：概念 → 数据流 → 计算 → 实现 → 自测。数字例子为教学构造；示意公式与完整原方法的区别在文中说明。</div>${deepPapers[p.id]?`<div class="info"><strong>新增：完整学术精读</strong><p>逐式解释、原文图表分析、代码核查、动手任务与自测。</p><a class="btn primary" href="deep/${deepPapers[p.id].slug}.html">打开 ${deepPapers[p.id].name} 完整精读 →</a></div>`:''}${readerTools('paper-lessons.md')}${lessonBlocks(p.lessons)}<details class="lesson-part source-overview"><summary>原论文速览、出处与链接</summary><div class="prose lesson-text">${p.html}</div></details><label class="check"><input type="checkbox" data-paper-check="${p.id}" ${state.papers.includes(p.id)?'checked':''}>已读并完成自己的阅读笔记</label>${noteArea(p.id)}`);}
function lab(){return intro('LEARN BY CHANGING','动一下参数，看概念怎样变化。','以下都是用于理解机制的教学数值，不是真实模型结果。先预测会发生什么，再拖动滑块验证。')+`<div class="lab-grid"><section class="card lab-card"><span class="tag">实验 01 · 多标签</span><h2>阈值改变，输出哪些情绪？</h2><p>同一条样本可以有多种情绪。sigmoid 概率独立，并不要求六个值相加等于 1。</p><div class="slider-row"><label for="threshold">判断阈值</label><input id="threshold" type="range" min="0" max="100" value="50"><output id="threshold-value" for="threshold">0.50</output></div><div class="bars" id="emotion-bars"></div><div class="result-box" id="emotion-result" aria-live="polite"></div><p style="margin-top:15px">判定规则：概率 ≥ 阈值。阈值降低往往增加预测正例，但精确率不一定更好；正式任务只在验证集调阈值。概率不是情绪强度。</p></section><section class="card lab-card"><span class="tag purple">实验 02 · 持续学习</span><h2>学完 C，还记得 A 和 B 吗？</h2><p>教学假设：A 学完时为 80%，B 学完时为 78%；学完 B 时 A 为 65%。拖动最终成绩观察变化。</p>${[['a',60,'场景 A'],['b',70,'场景 B'],['c',76,'场景 C']].map(([id,v,label])=>`<div class="slider-row"><label for="score-${id}">${label}</label><input id="score-${id}" type="range" min="0" max="100" value="${v}"><output id="value-${id}" for="score-${id}">${v}%</output></div>`).join('')}<div class="cl-viz" aria-hidden="true"><div class="cl-legend"><span><i class="first"></i>首次学完时</span><span><i class="final"></i>学完 C 后</span><span><i class="drop"></i>低于首次</span></div>${[['a','场景 A',80],['b','场景 B',78],['c','场景 C',0]].map(([k,l,f])=>`<div class="cl-row" id="cl-${k}"><span>${l}</span><div class="cl-track">${f?`<div class="cl-first" style="width:${f}%"></div>`:''}<div class="cl-final"></div></div><b class="cl-delta"></b></div>`).join('')}</div><div class="lab-metrics" id="cl-metrics"><div><strong id="metric-aa"></strong><small>AA · 最终平均准确率</small></div><div><strong id="metric-bwt"></strong><small>BWT · 后向迁移 / pp</small></div><div><strong id="metric-f"></strong><small>F · 非负遗忘 / pp</small></div></div><div class="formula" id="cl-formula"></div><div class="result-box" id="forget-result" aria-live="polite"></div><p style="margin-top:15px">F 使用包含最终阶段的历史最大值。BWT 可以为正；F 在此定义下不为负。新场景学不会时，遗忘很小也不够。</p></section></div><div class="info">想继续推导？<a href="#handbook/s5">查看完整性能矩阵与公式 →</a> · <a href="#handbook/s4">查看多标签与强度的区别 →</a></div>`;}
const labEmotions=[['快乐',.18],['悲伤',.82],['愤怒',.46],['恐惧',.61],['厌恶',.24],['惊讶',.35]];
const signed=v=>{const s=v.toFixed(1);return s==='-0.0'?'0.0':(+s>0?'+':'')+s;};
function setMetric(sel,to,format){const el=$(sel);if(typeof tweenNumber==='function')tweenNumber(el,el._value??0,to,{duration:420,format});else el.textContent=format(to);}
// Bars are built once and then updated in place so width/colour changes can animate.
function updateLab(){let t=Number($('#threshold').value)/100;$('#threshold-value').textContent=t.toFixed(2);const bars=$('#emotion-bars');if(!bars.children.length)bars.innerHTML=labEmotions.map(([n,v])=>`<div class="bar-row"><span>${n}</span><div class="bar-wrap"><div class="threshold-mark"></div><div class="bar-fill" style="width:${v*100}%"></div></div><span>${v.toFixed(2)}</span></div>`).join('');const picked=labEmotions.filter(([,v])=>v>=t).map(([n])=>n);labEmotions.forEach(([,v],i)=>{const row=bars.children[i],on=v>=t;row.classList.toggle('on',on);row.querySelector('.bar-fill').classList.toggle('selected',on);row.querySelector('.threshold-mark').style.left=t*100+'%';});$('#emotion-result').textContent=picked.length?`当前预测 ${picked.length} / 6 类：${picked.join('、')}`:'无类别超过阈值（需要检查阈值与模型校准）';let a=+$('#score-a').value,b=+$('#score-b').value,c=+$('#score-c').value;['a','b','c'].forEach((x,i)=>$('#value-'+x).textContent=[a,b,c][i]+'%');let aa=(a+b+c)/3,bwt=(a-80+b-78)/2,f=(Math.max(80,65,a)-a+Math.max(78,b)-b)/2;setMetric('#metric-aa',aa,v=>v.toFixed(1)+'%');setMetric('#metric-bwt',bwt,signed);setMetric('#metric-f',f,v=>v.toFixed(1));[['a',a,80],['b',b,78],['c',c,null]].forEach(([k,v,first])=>{const row=$('#cl-'+k),d=first===null?null:v-first,del=row.querySelector('.cl-delta');row.querySelector('.cl-final').style.width=v+'%';row.classList.toggle('drop',d!==null&&d<0);del.className='cl-delta'+(d===null?'':d<0?' neg':d>0?' pos':'');del.textContent=d===null?`新学 ${v}%`:`${d>0?'+':''}${d} pp`;});$('#cl-formula').innerHTML=`AA = (${a} + ${b} + ${c}) / 3 = <b>${aa.toFixed(1)}%</b><br>BWT = ((${a} − 80) + (${b} − 78)) / 2 = <b>${signed(bwt)} pp</b><br>F = ((max(80, 65, ${a}) − ${a}) + (max(78, ${b}) − ${b})) / 2 = <b>${f.toFixed(1)} pp</b>`;$('#cl-metrics').classList.toggle('warn',bwt<0);$('#forget-result').classList.toggle('warn',bwt<0);$('#forget-result').textContent=bwt<0?`旧场景平均下降 ${(-bwt).toFixed(1)} 个百分点。场景 C 当前为 ${c}%，还需同时判断新知识是否学会。`:`旧场景相对首次学完时平均提升 ${bwt.toFixed(1)} 个百分点。这是正后向迁移；仍需检查新场景表现。`;}
function quiz(){if(quizIndex>=questions.length){let score=answers.reduce((s,a,i)=>s+(a===questions[i][2]),0);if(score>state.quizBest){state.quizBest=score;save();}return intro('CHECK YOUR UNDERSTANDING','把记住的词，变成真正的理解。','自测用于发现知识缺口，不作为学术能力评分。')+`<section class="card quiz-card"><div class="quiz-dots" aria-hidden="true">${questions.map((q,i)=>`<i class="${answers[i]===q[2]?'ok':'miss'}"></i>`).join('')}</div><div class="quiz-score"><span data-count="${score}">${score}</span><small style="font-size:22px"> / ${questions.length}</small></div><h2>${score===questions.length?'核心概念已经连起来了。':'知道卡在哪里，就是下一步。'}</h2><p class="muted">错题会告诉你需要回到哪一节。读完后，用自己的例子再解释一遍。</p>${questions.map((q,i)=>`<div class="info">${answers[i]===q[2]?'✓':'↺'} ${esc(q[0])}<br>${esc(q[3])} <a href="#handbook/${q[4]}">回到手册 →</a></div>`).join('')}<button class="btn primary" id="restart-quiz">重新自测</button></section>`;}let q=questions[quizIndex],a=answers[quizIndex];return intro('CHECK YOUR UNDERSTANDING','先想一想，再看答案。',`${questions.length} 个关键问题，覆盖标签、实验协议、解释、持续学习与 2026-10 新增概念。每题作答后会给出原因。`)+`<section class="card quiz-card"><span class="quiz-count">第 ${quizIndex+1} 题 · 共 ${questions.length} 题</span><div class="quiz-dots" aria-hidden="true">${questions.map((qq,i)=>{const ans=answers[i];return `<i class="${i>quizIndex?'':ans===undefined?(i===quizIndex?'now':''):ans===qq[2]?'ok':'miss'}"></i>`;}).join('')}</div><h2 class="quiz-question ${a===undefined?'fresh':''}">${esc(q[0])}</h2><div class="options ${a===undefined?'fresh':''}">${q[1].map((t,i)=>`<button class="option ${a!==undefined?(i===q[2]?'correct':i===a?'wrong':''):''} ${a===i?'picked':''}" style="--i:${i}" data-answer="${i}" ${a!==undefined?'disabled':''}><span>${'ABC'[i]}</span>${esc(t)}</button>`).join('')}</div>${a!==undefined?`<div class="feedback"><strong>${a===q[2]?'理解正确。':'再想一层。'}</strong> ${esc(q[3])}<br><a href="#handbook/${q[4]}">查看相关知识 →</a></div><button class="btn primary" id="next-question">${quizIndex===questions.length-1?'查看本轮结果':'下一题 →'}</button>`:'<p class="mode-notice">选择最符合研究协议的一项。</p>'}</section>`;}
function notes(){let entries=Object.entries(state.notes).filter(([k,v])=>k!=='journal'&&v.trim());return intro('YOUR RESEARCH JOURNAL','给每一次理解，留下一点痕迹。','记录不懂的问题、实验想法和阅读收获。数据仅保存在当前浏览器，不会跨设备自动同步；建议定期导出。')+`<div class="actions"><button class="btn primary" id="export-data">导出进度与笔记 ↓</button><label class="btn import-label">导入备份<input type="file" id="import-data" accept=".json,application/json"></label><a class="btn" href="learning-roadmap.md" download>下载原学习路线</a><a class="btn" href="week-playbook.md" download>下载逐周行动手册</a><a class="btn" href="paper-lessons.md" download>下载论文精读讲义</a><a class="btn" href="learning_starter.py" download>下载入门练习脚本</a></div><div class="card" style="margin-top:22px">${noteArea('journal','自由笔记 · 本周最想弄懂的问题')}</div><div class="section-head"><h2>论文与阶段笔记</h2><small>${entries.length} 条记录</small></div>${entries.length?entries.map(([k,v])=>{let w=k.startsWith('week-')?weeks[+k.slice(5)-1]:null,p=COURSE.papers.find(p=>p.id===k);return `<article class="card note-card"><h3>${esc(w?`第 ${w.n} 周 · ${w.title}`:p?`${p.id} · ${p.title}`:k)}</h3><p>${esc(v)}</p><button class="btn small" ${w?`data-week="${w.n}"`:`data-paper="${k}"`}>继续编辑 →</button></article>`;}).join(''):'<div class="empty">还没有阶段或论文笔记。打开任意阅读卡，在底部写下你的思考。</div>'}`;}
function render(){const previousRing=document.querySelector('.ring-value')?.style.strokeDashoffset;const funcs={home,roadmap,papers,lab,quiz,handbook,notes};$('#main').innerHTML=funcs[page]();document.querySelectorAll('[data-page]').forEach(el=>{el.classList.toggle('active',el.dataset.page===page);if(el.dataset.page===page)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});enhancePage();const newRing=document.querySelector('.ring-value');if(newRing&&previousRing!==undefined&&previousRing!==newRing.style.strokeDashoffset&&!reduceMotion.matches){const target=newRing.style.strokeDashoffset;newRing.style.strokeDashoffset=previousRing;requestAnimationFrame(()=>{if(newRing.isConnected)newRing.style.strokeDashoffset=target;});}$('#breadcrumb').textContent=({home:'学习总览',roadmap:'成长路线',papers:'论文阅读室',lab:'概念实验台',quiz:'理解自测',handbook:'完整学习手册',notes:'我的学习笔记'})[page];document.title=$('#breadcrumb').textContent+' · 情绪研究学习室';if(page==='lab')updateLab();if(!storageOK)$('#main').insertAdjacentHTML('afterbegin','<p class="info reduced">当前浏览器存储不可用或旧数据无法读取。请使用导出备份保留本轮记录。</p>');if(typeof motionEnhance==='function')motionEnhance();}
function navigate(){const [p,arg]=location.hash.slice(1).split('/');if(p==='main'){document.querySelector('#main').focus();return;}if(/^s\d+$/.test(p)&&COURSE.sections.some(s=>s.id===p)){location.hash='handbook/'+p;return;}page=['home','roadmap','papers','lab','quiz','handbook','notes'].includes(p)?p:'home';if(page==='roadmap')routeFilter=['fine','cross','common','research'].includes(arg)?arg:'all';if(page==='handbook'&&COURSE.sections.some(s=>s.id===arg))bookSection=arg;if($('#reader').open)$('#reader').close();revealNext();render();window.scrollTo({top:0,behavior:'instant'});}
window.addEventListener('hashchange',()=>{if(document.startViewTransition&&!matchMedia('(prefers-reduced-motion:reduce)').matches)document.startViewTransition(navigate).ready.catch(()=>{});else navigate();});
window.addEventListener('pageshow',e=>{if(!e.persisted)return;try{state=validate(JSON.parse(localStorage.getItem(KEY)||'null')||blank());storageOK=true;}catch(err){storageOK=false;}navigate();});
document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;if(el.dataset.lessons){document.querySelectorAll('#reader .lesson-stack details').forEach(d=>d.open=el.dataset.lessons==='expand');}if(el.dataset.resumeNotes)location.hash='notes';if(el.dataset.week)openWeek(+el.dataset.week);if(el.dataset.paper)openPaper(el.dataset.paper);if(el.dataset.routeFilter){routeFilter=el.dataset.routeFilter;revealNext('partial');render();}if(el.dataset.paperFilter){paperFilter=el.dataset.paperFilter;revealNext('partial');render();}if(el.dataset.section)location.hash='handbook/'+el.dataset.section;if(el.dataset.answer!==undefined){const pick=+el.dataset.answer;if(pick===questions[quizIndex][2]&&typeof celebrate==='function')celebrate(el);answers[quizIndex]=pick;render();}if(el.id==='next-question'){quizIndex++;render();}if(el.id==='restart-quiz'){quizIndex=0;answers=[];render();}if(el.id==='close-dialog')$('#reader').close();if(el.classList.contains('close-on-nav'))$('#reader').close();if(el.id==='export-data'){state.lastExportAt=new Date().toISOString();save();const blob=new Blob([JSON.stringify({version:1,exportedAt:new Date().toISOString(),...state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='emotion-learning-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('备份已导出');}});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.note){state.notes[el.dataset.note]=el.value;save(true);}if(el.id==='paper-search'){paperSearch=el.value;$('#paper-results').innerHTML=paperCards();}if(['threshold','score-a','score-b','score-c'].includes(el.id))updateLab();});
document.addEventListener('change',async e=>{const el=e.target;if(el.dataset.weekCheck){const n=+el.dataset.weekCheck;if(el.checked&&typeof celebrate==='function')celebrate(el);state.weeks=state.weeks.filter(x=>x!==n);if(el.checked)state.weeks.push(n);save();render();}if(el.dataset.paperCheck){const id=el.dataset.paperCheck;if(el.checked&&typeof celebrate==='function')celebrate(el);state.papers=state.papers.filter(x=>x!==id);if(el.checked)state.papers.push(id);state.inProgress=state.inProgress.filter(x=>x!==id);save();if(page==='papers')$('#paper-results').innerHTML=paperCards();else render();}if(el.id==='paper-depth'){paperDepth=el.value;$('#paper-results').innerHTML=paperCards();if(typeof motionPulse==='function')motionPulse($('#paper-results'));}if(el.id==='paper-status'){paperStatus=el.value;$('#paper-results').innerHTML=paperCards();if(typeof motionPulse==='function')motionPulse($('#paper-results'));}if(el.id==='import-data'&&el.files[0]){try{if(el.files[0].size>2000000)throw Error('文件过大');const raw=JSON.parse(await el.files[0].text());if(raw.version!==1||!Array.isArray(raw.weeks)||!Array.isArray(raw.papers))throw Error('不是本网站的备份文件');const next=validate(raw);if(!confirm('导入将替换当前浏览器中的学习进度和笔记。建议先导出当前记录。继续导入？'))return;state=next;save();render();toast('备份已导入');}catch(err){toast('无法导入：'+err.message);}}});
document.addEventListener('keydown',e=>{if(e.target.classList.contains('import-label')&&(e.key==='Enter'||e.key===' ')){e.preventDefault();$('#import-data').click();}});
$('#reader').addEventListener('click',e=>{if(e.target===$('#reader')){const r=$('#reader').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#reader').close();}});
window.learningReady=true;
navigate();

